@page "/recipes/{categorySlug}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@_categoryName Recipes - RecipeShare</PageTitle>

<h1>@_categoryName</h1>

@if (_recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="list-group">
        @foreach (var recipe in _recipes)
        {
            <a href="recipe/@recipe.Id" class="list-group-item list-group-item-action">
                <div class="d-flex w-100 justify-content-between">
                    <h5 class="mb-1">@recipe.Title</h5>
                    <small>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</small>
                </div>
                <p class="mb-1">@recipe.Ingredients.Count ingredients · @recipe.Steps.Count steps</p>
            </a>
        }
    </div>
}

<div class="mt-3">
    <a href="recipes" class="btn btn-secondary">← All Categories</a>
</div>

@code {
    [Parameter] public string CategorySlug { get; set; } = string.Empty;

    private List<Models.Recipe> _recipes = [];
    private string _categoryName = string.Empty;

    protected override void OnParametersSet()
    {
