              style="font-size: 1.5rem; cursor: pointer; color: @(star <= _selectedRating ? "gold" : "#ccc");">
            ★
        </span>
    }

    @if (_submitted)
    {
        <span class="ms-3 text-success">Thanks for rating!</span>
    }

    <div class="mt-1 text-muted small">
        Average: @CurrentRating.ToString("F1") ⭐ (@RatingCount ratings)
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _selectedRating;
    private bool _submitted;

    private void Rate(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}
