+                    <h5 class="mb-1">@recipe.Title</h5>
+                    <small>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</small>
+                </div>
+                <p class="mb-1">@recipe.Ingredients.Count ingredients · @recipe.Steps.Count steps</p>
+            </a>
+        }
+    </div>
+}
+
+<div class="mt-3">
+    <a href="recipes" class="btn btn-secondary">← All Categories</a>
+</div>
+
