@page "/recipes"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes - RecipeShare</PageTitle>

<h1>Browse Recipes</h1>
<p>Select a category to explore recipes.</p>

<div class="row">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">@category.Value</h5>
                    <a href="recipes/@category.Key" class="btn btn-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (_recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <h1>@_recipe.Title</h1>
    <p class="text-muted">Category: @_recipe.Category</p>

    <StarRating RecipeId="@_recipe.Id" CurrentRating="@_recipe.AverageRating" RatingCount="@_recipe.RatingCount" />

    <h3 class="mt-4">Ingredients</h3>
    <ul>
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in _recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <a href="recipes/@_recipe.CategorySlug" class="btn btn-secondary mt-3">← Back to @_recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span role="button" @onclick="() => Rate(star)"
              style="font-size: 1.5rem; cursor: pointer; color: @(star <= _selectedRating ? "gold" : "#ccc");">
            ★
        </span>
    }

    @if (_submitted)
    {
        <span class="ms-3 text-success">Thanks for rating!</span>
    }

    <div class="mt-1 text-muted small">
        Average: @CurrentRating.ToString("F1") ⭐ (@RatingCount ratings)
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _selectedRating;
    private bool _submitted;

    private void Rate(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

